<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRouter } from 'vue-router'
import { deleteWork, getMyWorks, type Work } from '@/api/works'
const router = useRouter(); const records = ref<Work[]>([]); const loading = ref(true); const total = ref(0); const page = ref(1); const labels: Record<string,string> = { PENDING:'审核中', PUBLISHED:'已发布', REJECTED:'已驳回', OFFLINE:'已下架' }
async function load(next = page.value) { loading.value = true; page.value = next; try { const { data } = await getMyWorks({ page: page.value, pageSize: 10 }); records.value = data.records; total.value = data.total } finally { loading.value = false } }
onMounted(load)
async function remove(work: Work) { try { await ElMessageBox.confirm(`确定删除作品「${work.title}」吗？删除后不可恢复。`, '删除作品'); await deleteWork(work.id); ElMessage.success('作品已删除'); await load() } catch { /* 取消删除 */ } }
</script>
<template><main class="my-works"><section class="content"><div class="heading"><div><p class="eyebrow">MY WORKS</p><h1>我的作品</h1><p>查看作品审核状态和互动数据。</p></div><el-button type="primary" @click="router.push('/works/create')">发布作品</el-button></div><div v-loading="loading" class="list"><el-empty v-if="!loading&&!records.length" description="还没有发布作品" /><article v-for="work in records" :key="work.id"><div class="thumb"><img v-if="work.mediaType==='IMAGE'" :src="work.mediaUrl" :alt="work.title" /><span v-else>VIDEO</span></div><div class="info"><h2>{{ work.title }}</h2><p>{{ work.danceType }} · {{ work.likeCount }} 赞 · {{ work.commentCount }} 评论</p><el-tag :type="work.auditStatus==='PUBLISHED'?'success':work.auditStatus==='REJECTED'?'danger':'warning'">{{ labels[work.auditStatus] }}</el-tag><p v-if="work.auditReason" class="reason">驳回原因：{{ work.auditReason }}</p></div><div class="actions"><el-button link type="primary" @click="router.push(`/works/${work.id}`)">查看详情</el-button><el-button link @click="router.push(`/works/${work.id}/edit`)">编辑</el-button><el-button link type="danger" @click="remove(work)">删除</el-button></div></article><el-pagination v-if="total>10" v-model:current-page="page" layout="prev, pager, next" :page-size="10" :total="total" @current-change="load" class="pager" /></div></section></main></template>
<style scoped>.my-works{min-height:100vh;background:transparent;color:#fff}.content{max-width:1040px;margin:auto;padding:64px 24px}.heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:30px}.eyebrow{margin:0 0 10px;color:#f0a8fb;font-size:12px;font-weight:700;letter-spacing:2px}.heading h1{margin:0 0 10px;font-size:42px}.heading p:last-child{margin:0;color:rgba(255,255,255,.7)}.list{min-height:240px}.list article{display:flex;align-items:center;gap:18px;margin-bottom:14px;padding:16px 20px;border:1px solid rgba(244,205,250,.24);border-radius:14px;background:rgba(54,12,70,.8);box-shadow:0 14px 32px rgba(25,3,40,.18)}.thumb{width:116px;height:78px;display:grid;place-items:center;flex-shrink:0;overflow:hidden;border-radius:8px;background:linear-gradient(135deg,#35104b,#c52fda);color:#fff;font-size:12px}.thumb img{width:100%;height:100%;object-fit:cover}.info{flex:1}.info h2{margin:0 0 6px;color:#fff;font-size:17px}.info p{margin:0 0 8px;color:rgba(255,255,255,.7);font-size:12px}.reason{color:#ffb1c1!important}.pager{justify-content:center;margin-top:22px}@media(max-width:600px){.heading{align-items:start;gap:18px;flex-direction:column}.list article{align-items:flex-start;flex-wrap:wrap}.list article .el-button{margin-left:134px}}
</style>
